start_daemon.description:
Whether to start fetchmail as a daemon (set to 'yes' or 'no'). This controls the START_DAEMON variable in the init config.
      "enum": [
        "yes",
        "no"
      ]
    }

actionstart.default:
ipfw show | fgrep -c -m 1 -s 'table(<table>)' > /dev/null 2>&1 || (
    num=$(ipfw show | awk 'BEGIN { b = <lowest_rule_num> } { if ($1 == b) { b = $1 + 1 } } END { print b }');
    ipfw -q add "$num" <blocktype> <block> from table\(<table>\) to me <port>; echo "$num" > "<startstatefile>"
  )

